/**
 * A 160 × 116, one-bit raster derived from the existing public
 * `echelon-assets/logo dots orange.png` asset. The orange source is
 * intentionally rendered as black for thermal paper.
 */
export const ECHELON_LOGO_WIDTH = 160;
export const ECHELON_LOGO_HEIGHT = 116;
export const ECHELON_LOGO_RASTER_BASE64 =
  "";

type EposLogoRasterCandidate = {
  width: number;
  height: number;
  base64: string;
};

const BASE64_PATTERN = /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/;

function base64Bytes(value: string): Uint8Array {
  if (!BASE64_PATTERN.test(value)) {
    throw new Error("Echelon ePOS logo raster must be valid Base64.");
  }
  return Uint8Array.from(atob(value), (character) => character.charCodeAt(0));
}

export function validateEchelonLogoRaster(
  candidate: EposLogoRasterCandidate = {
    width: ECHELON_LOGO_WIDTH,
    height: ECHELON_LOGO_HEIGHT,
    base64: ECHELON_LOGO_RASTER_BASE64,
  },
): void {
  if (
    !Number.isInteger(candidate.width) ||
    !Number.isInteger(candidate.height) ||
    candidate.width <= 0 ||
    candidate.height <= 0 ||
    candidate.width % 8 !== 0
  ) {
    throw new Error("Echelon ePOS logo width must be byte-aligned.");
  }
  const bytes = base64Bytes(candidate.base64);
  const expectedBytes = (candidate.width / 8) * candidate.height;
  if (bytes.length !== expectedBytes) {
    throw new Error("Echelon ePOS logo raster does not match its declared geometry.");
  }
  if (bytes.every((byte) => byte === 0)) {
    throw new Error("Echelon ePOS logo raster must contain at least one black pixel.");
  }
}

validateEchelonLogoRaster();
